import { useState } from 'react';

export default function {{component_name}}() {
  const [step, setStep] = useState(0);
  const [data, setData] = useState({ name: '', email: '', plan: '' });
  const steps = [
    <input key="n" placeholder="Name" value={data.name} onChange={(e) => setData({ ...data, name: e.target.value })} />,
    <input key="e" placeholder="Email" value={data.email} onChange={(e) => setData({ ...data, email: e.target.value })} />,
    <select key="p" value={data.plan} onChange={(e) => setData({ ...data, plan: e.target.value })}>
      <option value="">Pick plan</option>
      <option value="free">Free</option>
      <option value="pro">Pro</option>
    </select>,
  ];

  return (
    <div>
      <p>Step {step + 1} / {steps.length}</p>
      {steps[step]}
      <div>
        <button onClick={() => setStep((s) => Math.max(0, s - 1))} disabled={step === 0}>Back</button>
        <button onClick={() => setStep((s) => Math.min(steps.length - 1, s + 1))} disabled={step === steps.length - 1}>Next</button>
      </div>
    </div>
  );
}
